import{_ as e,o,c as a,a5 as r}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"HJ87 密码强度等级","description":"描述 密码按如下规则进行计分，并根据不同的得分为密码进行安全等级划分。 一、密码长度: 5 分: 小于等于4 个字符 10 分: 5 到7 字符 25 分: 大于等于8 个字符 二、字母: 0 分: 没有字母 10 分: 密码里的字母全都是小（大）写字母 20 分: 密码里的字母。","frontmatter":{"title":"HJ87 密码强度等级","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 密码按如下规则进行计分，并根据不同的得分为密码进行安全等级划分。 一、密码长度: 5 分: 小于等于4 个字符 10 分: 5 到7 字符 25 分: 大于等于8 个字符 二、字母: 0 分: 没有字母 10 分: 密码里的字母全都是小（大）写字母 20 分: 密码里的字母。","sidebarWeight":65,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/HJ87 密码强度等级.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ87 密码强度等级.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ87 密码强度等级.md"}'),s={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ87 密码强度等级.md"};function l(n,t,i,c,u,_){return o(),a("div",null,[...t[0]||(t[0]=[r('<div><h1 id="hj87-密码强度等级" tabindex="-1">HJ87 密码强度等级 <a class="header-anchor" href="#hj87-密码强度等级" aria-label="Permalink to &quot;HJ87 密码强度等级&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ87 密码强度等级”的核心思路，并能把它用于实际开发或面试表达。 <strong>描述</strong> 密码按如下规则进行计分，并根据不同的得分为密码进行安全等级划分。</p></blockquote><p>一、密码长度: 5 分: 小于等于4 个字符 10 分: 5 到7 字符 25 分: 大于等于8 个字符</p><p>二、字母: 0 分: 没有字母 10 分: 密码里的字母全都是小（大）写字母 20 分: 密码里的字母符合”大小写混合“</p><p>三、数字: 0 分: 没有数字 10 分: 1 个数字 20 分: 大于1 个数字</p><p>四、符号: 0 分: 没有符号 10 分: 1 个符号 25 分: 大于1 个符号</p><p>五、奖励（只能选符合最多的那一种奖励）: 2 分: 字母和数字 3 分: 字母、数字和符号 5 分: 大小写字母、数字和符号 最后的评分标准: &gt;= 90: 非常安全 &gt;= 80: 安全（Secure） &gt;= 70: 非常强 &gt;= 60: 强（Strong） &gt;= 50: 一般（Average） &gt;= 25: 弱（Weak） &gt;= 0: 非常弱（Very_Weak）</p><p>对应输出为：</p><p>VERY_SECURE SECURE VERY_STRONG STRONG AVERAGE WEAK VERY_WEAK</p><p>请根据输入的密码字符串，进行安全评定。</p><p>注： 字母：a-z, A-Z 数字：0-9 符号包含如下： (ASCII码表可以在UltraEdit的菜单view-&gt;ASCII Table查看) !&quot;#$%&amp;&#39;()*+,-./ (ASCII码：0x21~0x2F) :;&lt;=&gt;?@ (ASCII码：0x3A~0x40) []^_` (ASCII码：0x5B~0x60) {|}~ (ASCII码：0x7B~0x7E)</p><p>提示: 1 &lt;= 字符串的长度&lt;= 300 <strong>输入描述：</strong> 输入一个string的密码 <strong>输出描述：</strong> 输出密码等级 <strong>示例1</strong> 输入： 38$@NoNoN ==复制== 输出： VERY_SECURE ==复制== 说明： 样例的密码长度大于等于8个字符，得25分；大小写字母都有所以得20分；有两个数字，所以得20分；包含大于1符号，所以得25分；由于该密码包含大小写字母、数字和符号，所以奖励部分得5分，经统计得该密码的密码强度为25+20+20+25+5=95分。 <strong>示例2</strong> 输入： Jl)M:+ ==复制== 输出： AVERAGE ==复制== 说明： 示例2的密码强度为10+20+0+25+0=55分。</p><p>def password_strength_optimized(password): length_score = digit_count = upper_count = lower_count = symbol_count = 0</p><h1 id="一、密码长度评分" tabindex="-1">一、密码长度评分 <a class="header-anchor" href="#一、密码长度评分" aria-label="Permalink to &quot;一、密码长度评分&quot;">​</a></h1><p>if len(password) &lt;= 4: length_score = 5 elif 5 &lt;= len(password) &lt;= 7: length_score = 10 else: length_score = 25</p><h1 id="通过单次遍历密码-统计各类字符数量" tabindex="-1">通过单次遍历密码，统计各类字符数量 <a class="header-anchor" href="#通过单次遍历密码-统计各类字符数量" aria-label="Permalink to &quot;通过单次遍历密码，统计各类字符数量&quot;">​</a></h1><p>for char in password: if char.isdigit(): digit_count += 1 elif char.isupper(): upper_count += 1 elif char.islower(): lower_count += 1 elif not char.isalnum(): symbol_count += 1</p><h1 id="二、字母评分" tabindex="-1">二、字母评分 <a class="header-anchor" href="#二、字母评分" aria-label="Permalink to &quot;二、字母评分&quot;">​</a></h1><p>letter_score = 20 if upper_count &gt; 0 and lower_count &gt; 0 else 10 if upper_count &gt; 0 or lower_count &gt; 0 else 0</p><h1 id="三、数字评分" tabindex="-1">三、数字评分 <a class="header-anchor" href="#三、数字评分" aria-label="Permalink to &quot;三、数字评分&quot;">​</a></h1><p>digit_score = 20 if digit_count &gt; 1 else 10 if digit_count == 1 else 0</p><h1 id="四、符号评分" tabindex="-1">四、符号评分 <a class="header-anchor" href="#四、符号评分" aria-label="Permalink to &quot;四、符号评分&quot;">​</a></h1><p>symbol_score = 25 if symbol_count &gt; 1 else 10 if symbol_count == 1 else 0</p><h1 id="五、奖励评分" tabindex="-1">五、奖励评分 <a class="header-anchor" href="#五、奖励评分" aria-label="Permalink to &quot;五、奖励评分&quot;">​</a></h1><p>bonus_score = 5 if upper_count and lower_count and digit_count and symbol_count else <br> 3 if letter_score and digit_count and symbol_count else <br> 2 if letter_score and digit_count else 0</p><h1 id="计算总分" tabindex="-1">计算总分 <a class="header-anchor" href="#计算总分" aria-label="Permalink to &quot;计算总分&quot;">​</a></h1><p>total_score = length_score + letter_score + <br> digit_score + symbol_score + bonus_score</p><h1 id="判断密码等级" tabindex="-1">判断密码等级 <a class="header-anchor" href="#判断密码等级" aria-label="Permalink to &quot;判断密码等级&quot;">​</a></h1><p>if total_score &gt;= 90: return &quot;VERY_SECURE&quot; elif total_score &gt;= 80: return &quot;SECURE&quot; elif total_score &gt;= 70: return &quot;VERY_STRONG&quot; elif total_score &gt;= 60: return &quot;STRONG&quot; elif total_score &gt;= 50: return &quot;AVERAGE&quot; elif total_score &gt;= 25: return &quot;WEAK&quot; else: return &quot;VERY_WEAK&quot;</p><h1 id="输入密码" tabindex="-1">输入密码 <a class="header-anchor" href="#输入密码" aria-label="Permalink to &quot;输入密码&quot;">​</a></h1><p>password = input()</p><h1 id="输出密码等级" tabindex="-1">输出密码等级 <a class="header-anchor" href="#输出密码等级" aria-label="Permalink to &quot;输出密码等级&quot;">​</a></h1><p>print(password_strength_optimized(password))</p></div>',1)])])}const h=e(s,[["render",l]]);export{d as __pageData,h as default};
